package com.didww.sdk.resource.smstrunkconfiguration;

import com.didww.sdk.internal.Redact;
import com.didww.sdk.resource.enums.SmsServerLocation;
import com.fasterxml.jackson.annotation.JsonIgnore;
import com.fasterxml.jackson.annotation.JsonProperty;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.Setter;

import java.util.List;

/**
 * The customer binds to DIDWW as an SMPP ESME. {@code systemId} and {@code password} are generated by DIDWW
 * and are never sent in a request. {@code serverLocation} is required when the trunk is created.
 */
@Getter
@Setter
public class SmppEsmeConfiguration extends SmsTrunkConfiguration {

    /** SMPP system_type, up to 12 characters. */
    @JsonProperty("system_type")
    private String systemType;

    /** Addresses the ESME may bind from. */
    @JsonProperty("allowed_ips")
    private List<String> allowedIps;

    @JsonProperty("server_location")
    private SmsServerLocation serverLocation;

    /** Generated SMPP system_id. Read-only. */
    @Setter(AccessLevel.NONE)
    @JsonProperty(value = "system_id", access = JsonProperty.Access.WRITE_ONLY)
    private String systemId;

    /** Generated SMPP bind password. Read-only. */
    @Setter(AccessLevel.NONE)
    @JsonProperty(value = "password", access = JsonProperty.Access.WRITE_ONLY)
    private String password;

    @Override
    @JsonIgnore
    public String getType() {
        return "smpp_esme";
    }

    /**
     * Masks the generated credentials. The wire payload is unaffected.
     */
    @Override
    public String toString() {
        return "SmppEsmeConfiguration("
                + "systemType=" + systemType
                + ", allowedIps=" + allowedIps
                + ", serverLocation=" + serverLocation
                + ", systemId=" + Redact.mask(systemId)
                + ", password=" + Redact.mask(password)
                + ")";
    }
}
